function ensureChat(){
  state.sessions = Array.isArray(state.sessions) ? state.sessions : [];
  let chat = state.sessions.find(x=>x.id===activeChatId);
  if(!chat){chat={id:String(Date.now()),title:'New conversation',updated:Date.now(),messages:[]};state.sessions.unshift(chat);activeChatId=chat.id;save();}
  return chat;
}
function renderChatMessages(){
  const chat=ensureChat(), box=$('#chatMessages');box.innerHTML='';
  if(!chat.messages.length){addMessage(tr('tutorWelcome'),'tutor');return;}
  chat.messages.forEach(m=>addMessage(m.content,m.role==='user'?'user':'tutor',false));
  box.scrollTop=box.scrollHeight;
}
function renderHistory(){
  state.sessions=Array.isArray(state.sessions)?state.sessions:[];
  $('#historyCount').textContent=state.sessions.length;
  const list=$('#chatHistoryList');list.innerHTML='';
  if(!state.sessions.length){const p=document.createElement('p');p.className='muted';p.textContent='Your saved conversations appear here.';list.append(p);return;}
  state.sessions.slice(0,15).forEach(c=>{const b=document.createElement('button');b.className='history-item'+(c.id===activeChatId?' active':'');const title=document.createElement('b');title.textContent=c.title||'Conversation';const small=document.createElement('small');small.textContent=new Date(c.updated).toLocaleString();b.append(title,small);b.onclick=()=>{activeChatId=c.id;renderHistory();renderChatMessages()};list.append(b)});
}
