const levelRoadmap=[{code:"A1",name:"Curious Beginner",xp:0},{code:"A2",name:"Brave Explorer",xp:100},{code:"B1",name:"Confident Adventurer",xp:250},{code:"B2",name:"Fluent Pathfinder",xp:450},{code:"C1",name:"Language Hero",xp:700},{code:"C2",name:"Master Storyteller",xp:1000}];
const adventures=[
{id:"market",title:"The Mystery of the Missing Mango",level:"A1",tier:"easy",emoji:"🦊",hero:"Mia the fox",intro:"A sunny morning turns into a tiny mystery at the town market.",text:["Elena llega al mercado temprano. El sol brilla y las tiendas están llenas de frutas de muchos colores. Mia, una zorra pequeña con una mochila amarilla, la espera junto a un puesto de mangos.","—¡Buenos días! —dice Mia—. Hoy quiero preparar una tarta para mi abuela, pero… ¡ha desaparecido el mango más grande!","El vendedor mira debajo de la mesa. Elena busca detrás de las cajas. No hay ningún mango. De pronto, Mia escucha un ruido suave: crac, crac, crac. El sonido viene de una cesta azul.","Dentro de la cesta hay un erizo pequeño. Tiene una hoja en la cabeza y está sentado junto al mango. No quería robarlo; simplemente tenía hambre y se había perdido.","—No pasa nada —dice Elena—. Podemos compartir la fruta y ayudarte a encontrar tu casa.","Mia sonríe. Compra dos mangos más y los tres caminan hacia el parque. Allí vive el erizo, debajo de un árbol grande. La tarta tendrá que esperar, pero Elena y Mia han encontrado algo mejor: un nuevo amigo."],words:[["el mercado","market"],["desaparecer","to disappear"],["la cesta","basket"],["perderse","to get lost"],["compartir","to share"]],question:"¿Dónde encuentran al erizo?",answers:["En una cesta azul","Debajo de la mesa","En una tienda"],correct:0,explain:"El erizo está dentro de una cesta azul, junto al mango."},
{id:"train",title:"A Ticket to the Coast",level:"A2",tier:"medium",emoji:"🐻",hero:"Bruno the bear",intro:"A missed train becomes an unexpected journey with a new friend.",text:["Bruno llevaba semanas ahorrando para visitar la costa. Había preparado una pequeña maleta, comprado un mapa y anotado el nombre de una cafetería famosa por sus medialunas. Sin embargo, al llegar a la estación descubrió que su tren había salido hacía cinco minutos.","—¡No puede ser! —murmuró. Miró el reloj, volvió a mirar el billete y respiró profundamente. La siguiente salida era dentro de dos horas.","Una mujer mayor que estaba sentada cerca le preguntó si necesitaba ayuda. Se llamaba Rosa y viajaba al mismo pueblo para visitar a su nieta. Le explicó que había un autobús que salía desde la terminal de la otra calle, aunque el trayecto era un poco más largo.","Bruno dudó. El autobús costaba menos, pero no conocía la ruta. Rosa le enseñó cómo llegar y le recomendó comprar agua antes de salir. A cambio, Bruno le ayudó a llevar una bolsa pesada hasta la parada.","Durante el viaje hablaron de sus ciudades, de la comida que echaban de menos y de los lugares que querían conocer. Cuando llegaron, Rosa invitó a Bruno a tomar un café con su familia.","Bruno llegó a la costa más tarde de lo previsto, pero comprendió que un plan diferente también puede convertirse en una buena historia."],words:[["ahorrar","to save money"],["la salida","departure"],["murmurar","to murmur"],["el trayecto","journey / route"],["echar de menos","to miss"],["previsto","planned / expected"]],question:"¿Por qué Bruno toma el autobús?",answers:["Porque es más rápido","Porque Rosa le explica una alternativa","Porque el tren está lleno"],correct:1,explain:"Rosa le recomienda el autobús que sale desde otra terminal."},
{id:"letter",title:"The Letter That Changed the Village",level:"B1",tier:"hard",emoji:"🦉",hero:"Ollie the owl",intro:"A forgotten letter reveals why an old lighthouse must be saved.",text:["Cuando Clara heredó la pequeña casa de su tío, no imaginaba que encontraría una caja de cartas escondida detrás de una estantería. La mayoría eran postales antiguas, recibos y fotografías de un pueblo costero que había cambiado mucho con los años.","Entre los papeles había una carta sin enviar, fechada treinta años atrás. Su tío escribía sobre el faro abandonado y sobre un proyecto comunitario que nunca llegó a realizarse. Según la carta, el faro no solo guiaba a los barcos: también servía como refugio durante las tormentas y como punto de encuentro para los vecinos.","Clara decidió investigar. Visitó el archivo municipal, habló con pescadores jubilados y encontró planos que demostraban que el edificio podía restaurarse. No obstante, el ayuntamiento consideraba que la reparación sería demasiado costosa.","En lugar de rendirse, Clara organizó una reunión abierta. Preparó fotografías, calculó los materiales necesarios y propuso que los habitantes colaboraran con pequeñas donaciones y jornadas de trabajo voluntario. Al principio asistieron pocas personas, pero la historia de la carta despertó curiosidad.","Un antiguo carpintero ofreció sus herramientas. Una profesora propuso organizar visitas escolares. Los jóvenes diseñaron una campaña para recaudar fondos. Poco a poco, el proyecto dejó de pertenecer a Clara y se convirtió en una iniciativa de todo el pueblo.","Meses después, la luz del faro volvió a encenderse. Clara colocó la carta en una vitrina, no como recuerdo de algo perdido, sino como prueba de que una idea puede esperar muchos años antes de encontrar a las personas adecuadas."],words:[["heredar","to inherit"],["estantería","bookshelf"],["refugio","shelter"],["rendirse","to give up"],["recaudar fondos","to raise funds"],["vitrina","display case"]],question:"¿Qué hace que el proyecto del faro tenga éxito?",answers:["Una gran empresa lo compra","Clara involucra a toda la comunidad","El ayuntamiento cambia de opinión inmediatamente"],correct:1,explain:"El proyecto crece cuando los vecinos aportan tiempo, habilidades e ideas."},
{id:"garden",title:"A Garden Above the City",level:"B2",tier:"hard",emoji:"🌱",hero:"Mia and the neighbours",intro:"A rooftop garden forces a neighbourhood to negotiate, cooperate and rethink public space.",text:["Durante años, la azotea del edificio había sido un lugar olvidado: una superficie de cemento donde solo se acumulaban macetas rotas y objetos que nadie quería conservar. Todo cambió cuando Inés, una arquitecta que acababa de mudarse al barrio, propuso convertirla en un jardín comunitario.","La idea parecía sencilla, pero pronto surgieron desacuerdos. Algunos vecinos temían el ruido; otros dudaban de que el edificio pudiera soportar el peso de la tierra y los depósitos de agua. La administración exigió un informe técnico antes de autorizar cualquier obra.","En lugar de insistir, Inés organizó una reunión y pidió a cada persona que explicara sus preocupaciones. Un ingeniero voluntario calculó la carga máxima, mientras que varios residentes mayores compartieron sus conocimientos sobre plantas resistentes al viento.","El proyecto se puso en marcha con un presupuesto reducido y materiales reutilizados. Meses después, la azotea no solo producía hierbas y verduras: también se había convertido en un espacio donde personas que apenas se saludaban empezaban a colaborar.","Inés comprendió que el éxito no dependía únicamente de diseñar un jardín atractivo, sino de crear un proceso en el que todos pudieran participar."],words:[["la azotea","rooftop"],["el desacuerdo","disagreement"],["soportar","to support / withstand"],["la carga","load / weight"],["reutilizado","reused"],["colaborar","to collaborate"]],question:"¿Qué permitió que el proyecto avanzara?",answers:["Ignorar las dudas de los vecinos","Escuchar las preocupaciones y buscar soluciones compartidas","Comprar materiales más caros"],correct:1,explain:"La reunión permitió identificar problemas y encontrar soluciones entre todos."},
{id:"archive",title:"The Archive of Unfinished Voices",level:"C1",tier:"hard",emoji:"📜",hero:"Ollie the owl",intro:"An archivist discovers that preserving a town's history means confronting what was left out.",text:["Cuando el ayuntamiento anunció la digitalización del archivo municipal, la noticia se presentó como una operación puramente técnica: escanear documentos, catalogarlos y facilitar su consulta. Para Lucía, responsable del proyecto, aquella explicación resultaba insuficiente. Un archivo no era un depósito neutral, sino el resultado de decisiones sobre qué merecía conservarse y quién tenía derecho a dejar constancia de su experiencia.","Al revisar las cajas más antiguas, encontró cartas sin firmar, fotografías sin identificar y testimonios que nunca habían llegado a incorporarse al registro oficial. Muchos pertenecían a trabajadores migrantes que habían participado en la construcción del puerto, aunque sus nombres apenas aparecían en los documentos institucionales.","Lucía propuso incluir una colección oral y abrir un proceso de identificación pública. La iniciativa recibió críticas: algunos especialistas temían que los recuerdos personales se confundieran con hechos verificables. Ella respondió que la solución no consistía en equiparar todas las fuentes, sino en describir con rigor su procedencia, sus límites y el contexto en que habían sido producidas.","El equipo terminó diseñando un catálogo que distinguía entre documentos oficiales, testimonios y materiales de atribución incierta. Lejos de eliminar las contradicciones, las hacía visibles para que cada visitante pudiera comprender cómo se construye una memoria colectiva.","La digitalización no resolvió las disputas sobre el pasado, pero cambió la pregunta central: ya no se trataba solo de qué había ocurrido, sino de quién había tenido la oportunidad de contarlo."],words:[["la digitalización","digitisation"],["el depósito","repository / storage"],["la atribución","attribution"],["la procedencia","provenance / origin"],["equiparar","to equate"],["la memoria colectiva","collective memory"]],question:"¿Qué principio defendió Lucía?",answers:["Que todos los testimonios debían considerarse idénticos a los documentos oficiales","Que las fuentes debían contextualizarse y describirse con rigor","Que era mejor excluir los materiales sin firma"],correct:1,explain:"Lucía defendió distinguir las fuentes y explicar sus límites y contexto."},
{id:"horizon",title:"The Ethics of the Last Decision",level:"C2",tier:"hard",emoji:"🌌",hero:"Bruno the bear",intro:"A scientist must explain why a technically possible solution may still be socially unacceptable.",text:["El comité llevaba tres días deliberando sobre el sistema de predicción que la ciudad pretendía implantar para distribuir recursos durante las sequías. Sus defensores sostenían que el modelo permitiría anticiparse a la escasez con una precisión inédita; sus detractores advertían que la eficiencia estadística podía ocultar desigualdades históricas si los datos de partida reproducían patrones de exclusión.","A Bruno, responsable de evaluar el impacto público, le correspondía redactar la recomendación final. Los resultados eran prometedores, aunque no concluyentes: el sistema reducía el desperdicio en los escenarios simulados, pero asignaba un margen de error mayor a los barrios cuyos registros de consumo eran incompletos.","Una parte del comité quería aprobar el despliegue inmediato y corregir los fallos sobre la marcha. Otra exigía detener el proyecto hasta disponer de datos más representativos. Bruno consideró que ambas posturas simplificaban el dilema: aplazar la herramienta también tenía consecuencias, pero implementarla sin garantías podía convertir una limitación técnica en una injusticia institucional.","Su propuesta fue autorizar una prueba limitada, con supervisión independiente, criterios públicos de evaluación y un mecanismo de reclamación accesible. Además, exigió que cualquier decisión automatizada pudiera ser revisada por una persona y que los resultados se publicaran desglosados por zona.","Al presentar el informe, Bruno evitó afirmar que existía una solución impecable. Su argumento fue otro: cuando la incertidumbre no puede eliminarse, la responsabilidad consiste en hacerla visible, limitar sus efectos y permitir que quienes soportan el riesgo participen en la decisión."],words:[["deliberar","to deliberate"],["detractor","opponent / critic"],["concluyente","conclusive"],["el margen de error","margin of error"],["desglosado","disaggregated / broken down"],["impecable","flawless"]],question:"¿Cuál es la postura final de Bruno?",answers:["Aprobar el sistema sin restricciones","Rechazar cualquier uso de modelos predictivos","Permitir una prueba limitada con controles, transparencia y revisión humana"],correct:2,explain:"Bruno propone una implementación limitada y responsable, con supervisión y participación."}
];
const gameText={en:{minutes:"Complete 5 practice turns",sentences:"Write 3 complete sentences",story:"Read one story",read:"Read story",done:"Completed",check:"Check answer",right:"That’s right! Great reading.",wrong:"Not quite. Look for a clue in the story.",finish:"Finish story · earn 40 XP",words:"Words to collect",unlock:"Unlock next level"},es:{minutes:"Completa 5 turnos de práctica",sentences:"Escribe 3 frases completas",story:"Lee una historia",read:"Leer historia",done:"Completado",check:"Comprobar",right:"¡Correcto! Has leído muy bien.",wrong:"No exactamente. Busca una pista en la historia.",finish:"Terminar · ganar 40 XP",words:"Palabras nuevas",unlock:"Desbloquear nivel"},ru:{minutes:"Выполни 5 практических заданий",sentences:"Напиши 3 полных предложения",story:"Прочитай одну историю",read:"Читать историю",done:"Выполнено",check:"Проверить ответ",right:"Верно! Отлично читаешь.",wrong:"Не совсем. Найди подсказку в тексте.",finish:"Завершить · получить 40 XP",words:"Новые слова",unlock:"Открыть следующий уровень"}};
function gt(k){return (gameText[state.ui]||gameText.en)[k]||gameText.en[k]}
const roadNow=()=>[...levelRoadmap].reverse().find(x=>state.xp>=x.xp)||levelRoadmap[0];
const roadNext=()=>levelRoadmap.find(x=>state.xp<x.xp)||null;
function todayGameKey(){const d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")}
function giveQuestXP(id,condition,xp){const k=todayGameKey();state.questClaims[k]=state.questClaims[k]||[];if(condition&&!state.questClaims[k].includes(id)){state.questClaims[k].push(id);state.xp+=xp;save();}}
function renderGame(){
 const roadmap=$("#learningRoadmap");
 if(roadmap){roadmap.innerHTML="";levelRoadmap.forEach(stage=>{const count=adventures.filter(story=>story.level===stage.code).length,unlocked=state.xp>=stage.xp,card=document.createElement("button");card.type="button";card.className="roadmap-stage"+(unlocked?" is-unlocked":" is-locked")+(count?" has-stories":"");card.disabled=!count;const status=document.createElement("small");status.textContent=count?(unlocked?"AVAILABLE":"UNLOCK AT "+stage.xp+" XP"):"CHAPTERS COMING SOON";const code=document.createElement("b");code.textContent=stage.code;const name=document.createElement("span");name.textContent=stage.name;const detail=document.createElement("em");detail.textContent=count?count+" story chapter"+(count===1?"":"s"):stage.xp+" XP milestone";card.append(status,code,name,detail);if(count)card.addEventListener("click",()=>{const tier=stage.code==="A1"?"easy":stage.code==="A2"?"medium":"hard";document.querySelectorAll(".story-filter").forEach(button=>button.classList.toggle("active",button.dataset.storyFilter===tier));renderGame();document.querySelector("#storyGrid")?.scrollIntoView({behavior:"smooth",block:"start"});});roadmap.append(card)});}
 const grid=$("#questGrid");if(grid){grid.innerHTML="";const qs=[{id:"minutes",icon:"⏱️",title:gt("minutes"),desc:(state.activity[todayGameKey()]||0)+" / 5 turns",ok:(state.activity[todayGameKey()]||0)>=5,xp:20},{id:"sentences",icon:"✍️",title:gt("sentences"),desc:(state.sentences||0)+" / 3",ok:(state.dailySentences[todayGameKey()]||0)>=3,xp:15},{id:"story",icon:"📖",title:gt("story"),desc:(state.completedStories||[]).length+" stories",ok:(state.storyReads[todayGameKey()]||[]).length>0,xp:25}];qs.forEach(q=>{giveQuestXP(q.id,q.ok,q.xp);const c=document.createElement("article");c.className="quest-card"+((state.questClaims[todayGameKey()]||[]).includes(q.id)?" is-done":"");c.innerHTML='<span class="quest-emoji">'+q.icon+'</span><div class="quest-details"><b></b><small></small></div><span class="quest-reward"></span>';c.querySelector("b").textContent=q.title;c.querySelector("small").textContent=q.desc;c.querySelector(".quest-reward").textContent=(state.questClaims[todayGameKey()]||[]).includes(q.id)?"✓":"+"+q.xp+" XP";grid.append(c)});$("#homeXp").textContent=state.xp+" XP";}
 const cards=$("#storyGrid");if(cards){cards.innerHTML="";const filter=$(".story-filter.active")?.dataset.storyFilter||"all";adventures.filter(s=>filter==="all"||s.tier===filter).forEach(s=>{const done=state.completedStories.includes(s.id),need=(levelRoadmap.find(stage=>stage.code===s.level)||levelRoadmap[0]).xp;const c=document.createElement("article");c.className="story-card";const art=document.createElement("div");art.className="story-art story-"+s.tier;art.innerHTML='<span>'+s.emoji+'</span><small>'+s.level+' · '+s.tier.toUpperCase()+'</small>';const info=document.createElement("div");info.className="story-info";const h=document.createElement("h3");h.textContent=s.title;const hero=document.createElement("small");hero.textContent=s.hero;const p=document.createElement("p");p.textContent=s.intro;const b=document.createElement("button");b.className="primary-btn small";b.textContent=done?"✓ "+gt("done"):state.xp>=need?gt("read"): "Unlock at "+need+" XP";b.disabled=state.xp<need;b.onclick=()=>openAdventure(s);info.append(hero,h,p,b);c.append(art,info);cards.append(c)});}
 const current=roadNow(),next=roadNext();if($("#storyLevel"))$("#storyLevel").textContent=current.code+" · "+current.name;if($("#storyXpLabel"))$("#storyXpLabel").textContent=state.xp+" XP";if($("#storyXpBar"))$("#storyXpBar").style.width=(next?Math.min(100,state.xp/next.xp*100):100)+"%";if($("#storyProgressText"))$("#storyProgressText").textContent=next?(next.xp-state.xp)+" XP until "+next.name:"All levels unlocked!";
 if($("#totalXp"))$("#totalXp").textContent=state.xp;if($("#rankName"))$("#rankName").textContent=current.name;if($("#nextLevelHint"))$("#nextLevelHint").textContent=next?(next.xp-state.xp)+" XP until "+next.code+" · "+next.name:"All levels unlocked!";if($("#unlockLevelBtn")){$("#unlockLevelBtn").hidden=!next||state.xp<next.xp;$("#unlockLevelBtn").textContent=gt("unlock");}
}
function openAdventure(s){const box=$("#storyReader");box.hidden=false;box.innerHTML="";const head=document.createElement("div");head.className="reader-head";const title=document.createElement("h2");title.textContent=s.emoji+" "+s.title;const close=document.createElement("button");close.className="secondary-btn";close.textContent="×";close.onclick=()=>box.hidden=true;head.append(title,close);box.append(head);const meta=document.createElement("p");meta.className="reader-meta";meta.textContent=s.level+" · "+s.hero+" · "+Math.max(3,Math.round(s.text.join(" ").split(" ").length/130))+" min read";box.append(meta);const article=document.createElement("article");article.className="story-text";s.text.forEach(t=>{const p=document.createElement("p");p.textContent=t;article.append(p)});box.append(article);const vocab=document.createElement("div");vocab.className="reader-vocab";const vh=document.createElement("h3");vh.textContent=gt("words");vocab.append(vh);s.words.forEach(w=>{const row=document.createElement("div");row.className="reader-word";const a=document.createElement("b");a.textContent=w[0];const b=document.createElement("span");b.textContent=w[1];row.append(a,b);vocab.append(row)});box.append(vocab);const quiz=document.createElement("div");quiz.className="story-quiz";const q=document.createElement("h3");q.textContent=s.question;quiz.append(q);s.answers.forEach((a,i)=>{const label=document.createElement("label");label.className="quiz-option";const input=document.createElement("input");input.type="radio";input.name="storyAnswer";input.value=i;const span=document.createElement("span");span.textContent=a;label.append(input,span);quiz.append(label)});const check=document.createElement("button");check.className="primary-btn";check.textContent=gt("check");const feedback=document.createElement("p");feedback.className="quiz-feedback";check.onclick=()=>{const selected=quiz.querySelector("input:checked");if(!selected){feedback.textContent=gt("wrong");return}if(Number(selected.value)===s.correct){feedback.textContent=gt("right")+" "+s.explain;if(!state.completedStories.includes(s.id)){state.completedStories.push(s.id);}state.storyReads[todayGameKey()]=state.storyReads[todayGameKey()]||[];if(!state.storyReads[todayGameKey()].includes(s.id)){state.storyReads[todayGameKey()].push(s.id);state.xp+=40;giveQuestXP("story",true,25);}save();renderGame();renderStats();}else feedback.textContent=gt("wrong")};quiz.append(check,feedback);box.append(quiz);box.scrollIntoView({behavior:"smooth",block:"start"});}
$$(".story-filter").forEach(b=>b.addEventListener("click",()=>{$$(".story-filter").forEach(x=>x.classList.toggle("active",x===b));renderGame()}));
$("#unlockLevelBtn")?.addEventListener("click",()=>{const next=roadNext();if(!next||state.xp<next.xp)return;state.level=next.code;save();applyLanguage();updateTutorSettings();renderGame();toast("Level unlocked: "+next.code+" 🎉")});
const previousSendChat=sendChat;sendChat=async function(message){const count=(String(message).match(/[.!?。！？]/g)||[]).length;state.dailySentences[todayGameKey()]=(state.dailySentences[todayGameKey()]||0)+count;await previousSendChat(message);renderGame()};
renderGame();


